def make_v_pattern(grid, start_row, rows):
    """Create a 7-row V pattern starting from start_row"""
    rel_to_type = {0: 'N', 1: 'N', 2: 'W', 3: 'E', 4: 'W', 5: 'N', 6: 'N'}

    for i in range(7):
        r = start_row + i
        if r >= len(grid):
            break
        ctype = rel_to_type[i]

        if ctype == 'N':
            # Single center cell
            c = (start_row % 8) + (i + 1) * (1 if i < 4 else 0)
            grid[r][c] = 1
        elif ctype == 'W':
            # Left half (3 cells wide but only left side)
            for j in [-1, 0]:
                if 0 <= c+j < 18 and grid[r][c+j] != 2:
                    grid[r][c+j] = 1
        elif ctype == 'E':
            # Full width
            for j in [-1, 0, 1]:
                if 0 <= c+j < 18 and grid[r][c+j] != 2:
                    grid[r][c+j] = 1

    return grid

